class Solution {
public:
    string addBinary(string a, string b) {
        int i = (int)a.size() - 1, j = (int)b.size() - 1; // 从最低位（末尾字符）出发
        int carry = 0;                  // 进位，二进制逢二进一
        string out;
        while (i >= 0 || j >= 0 || carry) { // 还有位没加、或还剩进位，都要继续
            int total = carry;
            if (i >= 0) total += a[i--] - '0'; // 取 a 的当前位并左移下标
            if (j >= 0) total += b[j--] - '0'; // 取 b 的当前位并左移下标
            out.push_back(char('0' + total % 2)); // 本位结果 = 和对 2 取余
            carry = total / 2;                 // 新进位 = 和整除 2
        }
        reverse(out.begin(), out.end()); // 低位在前拼的，反转后输出
        return out;
    }
};

