func addBinary(a string, b string) string {
	i, j := len(a)-1, len(b)-1 // 从最低位（末尾字符）出发
	carry := 0                 // 进位，二进制逢二进一
	out := []byte{}
	for i >= 0 || j >= 0 || carry > 0 { // 还有位没加、或还剩进位，都要继续
		total := carry
		if i >= 0 { // 取 a 的当前位并左移下标
			total += int(a[i] - '0')
			i--
		}
		if j >= 0 { // 取 b 的当前位并左移下标
			total += int(b[j] - '0')
			j--
		}
		out = append(out, byte('0'+total%2)) // 本位结果 = 和对 2 取余
		carry = total / 2                    // 新进位 = 和整除 2
	}
	// 低位在前拼的，反转后输出；空结果兜底输出 0
	for l, r := 0, len(out)-1; l < r; l, r = l+1, r-1 {
		out[l], out[r] = out[r], out[l]
	}
	if len(out) == 0 {
		return "0"
	}
	return string(out)
}

