    unsigned int n = 0;
    for (char c : s) n = (n << 1) | unsigned(c - '0'); // 按二进制读入
    unsigned int ans = 0;
    for (int i = 0; i < 32; ++i) {  // 固定 32 轮，前导零同样参与反转
        ans = (ans << 1) | (n & 1); // 取 n 的最低位接到 ans 末尾
        n >>= 1;                    // 丢弃已处理位
    }
    string out;
    for (int i = 31; i >= 0; --i)   // 补齐 32 位输出（含前导零）
        out.push_back(char('0' + int((ans >> i) & 1)));
    cout << out << endl;
    return 0;
}

