def countBits(n):
    dp = [0] * (n + 1)          # dp[i]: i 的二进制中 1 的个数
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)   # 拆最低位：更小的子问题 + 最低位
